(function(root){'use strict';
const num=v=>Number(v).toPrecision(8),question=(prompt,expected,unit,steps)=>({prompt,expected,unit,steps});
function fields(form){if(!form)throw Error('The model inputs are unavailable.');const inputs={};for(const input of form.elements){if(!input.name||input.type==='file')continue;if(input.type==='checkbox')inputs[input.name]=input.checked;else if(input.type==='number'){if(!input.value.trim()||!Number.isFinite(Number(input.value)))throw Error('Complete the model inputs before continuing.');inputs[input.name]=Number(input.value);}else inputs[input.name]=input.value;}return inputs;}
function canonical(v){if(Array.isArray(v))return v.map(canonical);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).filter(k=>!['name','source','notes','title'].includes(k)).sort().map(k=>[k,canonical(v[k])]));return typeof v==='string'&&/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(v.trim())?Number(v):v;}
function metricRows(results){return Object.entries(results).filter(([,v])=>typeof v==='number'&&Number.isFinite(v)).map(([label,value])=>{const match=label.match(/\(([^()]*)\)\s*$/);return {id:label,label:match?label.slice(0,match.index).trim():label,unit:match?.[1]||'',value};});}
function build(id,title,inputs,results,exercise){const metrics=metricRows(results);if(!metrics.length)throw Error('This state has no finite numerical result to compare.');return {id,title,inputs:canonical(inputs),fingerprint:JSON.stringify(canonical(inputs)),metrics,question:exercise};}
function legacyQuestion(id,x,z){switch(id){
 case 'lifting':return question('An existing '+x.mass+' t load is lifted from '+x.deck+' m to '+x.hook+' m on a '+x.delta+' t displacement. Calculate the signed change in KG.',x.mass*(x.hook-x.deck)/x.delta,'m',['For an existing onboard weight, displacement stays fixed.','ΔKG = w(zhook − zold)/Δ.','ΔKG = '+num(x.mass*(x.hook-x.deck)/x.delta)+' m.']);
 case 'trim':return question('If '+x.mass+' t is loaded and TPC remains '+x.tpc+' t/cm, calculate the parallel sinkage.',x.mass/x.tpc,'cm',['Parallel sinkage in cm = loaded mass / TPC.','Sinkage = '+num(x.mass/x.tpc)+' cm.']);
 case 'tank':return question('The rectangular tank is '+x.length+' × '+x.breadth+' × '+x.height+' m, filled to '+x.fill+'%, with liquid density '+x.density+' t/m³. Calculate the liquid mass.',x.length*x.breadth*x.height*x.fill/100*x.density,'t',['Liquid volume = length × breadth × height × fill fraction.','Mass = density × volume.','m = '+num(x.length*x.breadth*x.height*x.fill/100*x.density)+' t.']);
 case 'pump':{const flow=z.results['Operating flow (m3/h)'];return question('The calculated forward flow is '+num(flow)+' m³/h. At a constant flow, how much liquid is delivered in 15 minutes?',flow/4,'m³',['15 minutes = 0.25 hour.','Volume = flow × time.','V = '+num(flow/4)+' m³.']);}
 case 'crank':return question('The two near-bottom deflection readings are '+x.b1+' and '+x.b2+' µm. Calculate the model’s estimated bottom reading.',(x.b1+x.b2)/2,'µm',['The model uses the arithmetic mean of the two near-bottom readings.','B = (b1 + b2)/2.','B = '+num((x.b1+x.b2)/2)+' µm.']);
 case 'faults':{const count=z.results['Flagged checks'];return question('The current tree flags '+count+' of its six observations. What percentage of observations is flagged? This is a count, not a failure probability.',count/6*100,'%',['Divide the number of flagged observations by all six observations.','Multiply the fraction by 100.','Flagged share = '+num(count/6*100)+'%.']);}
 case 'rlc':return question('For L = '+x.l+' H and C = '+x.cMicro+' µF, calculate the ideal series resonance frequency.',z.f0,'Hz',['Convert capacitance from µF to F.','f0 = 1/(2π√(LC)).','f0 = '+num(z.f0)+' Hz.']);
 case 'heat':return question('The hot stream enters at '+x.hotIn+' °C and leaves at '+num(z.hotOut)+' °C. Its mass flow is '+x.mHot+' kg/s and cp is '+x.cpHot+' kJ/(kg·K). Calculate the heat removed.',z.duty,'kW',['Q̇ = ṁ cp (Tin − Tout).','kg/s × kJ/(kg·K) × K gives kW.','Q̇ = '+num(z.duty)+' kW.']);
 case 'current':return question('The vector sum gives a speed over ground of '+num(z.sog)+' kn. At this constant speed, calculate the distance travelled in 2.5 hours.',z.sog*2.5,'NM',['One knot is one nautical mile per hour.','Distance = speed over ground × time.','d = '+num(z.sog*2.5)+' NM.']);
 case 'finance':return question('The first end-of-year cash flow is '+x.annual+' currency units and the effective annual discount rate is '+x.rate+'%. Calculate its present value at year zero.',x.annual/(1+x.rate/100),'currency',['Convert the percentage rate to a fraction.','PV1 = CF1/(1+r).','PV1 = '+num(x.annual/(1+x.rate/100))+' currency units.']);
 case 'beam':return question('The calculated left reaction is '+num(z.left)+' kN. Convert this signed force to newtons.',z.left*1000,'N',['1 kN = 1000 N.','Preserve the force sign.','Rleft = '+num(z.left*1000)+' N.']);
 case 'transient':return question('The first-order model has time constant τ = '+num(z.tau)+' s. Calculate the time corresponding to three time constants.',3*z.tau,'s',['t = 3τ.','t = '+num(3*z.tau)+' s.','A simple first-order rise has completed 1−exp(−3), about 95.02%, of its total change at this time.']);
 case 'ideal-cycle':return question('This ideal cycle adds '+num(z.Qin)+' kJ and rejects '+num(z.Qout)+' kJ of heat per cycle. Calculate the net work.',z.work,'kJ',['For the closed cycle, net work = heat added − heat rejected.','Wnet = Qin − Qout.','Wnet = '+num(z.work)+' kJ.']);
 case 'pump-suction':return z.operating?question('The calculated hydraulic power is '+num(z.hydraulicPower)+' kW and pump efficiency is '+x.efficiency+'. Calculate the shaft-power estimate.',z.hydraulicPower/x.efficiency,'kW',['Shaft input = hydraulic output / efficiency.','Pshaft = Phyd/η.','Pshaft = '+num(z.hydraulicPower/x.efficiency)+' kW.']):question('The reservoir pressure is '+x.surface+' kPa(a) and vapour pressure is '+x.vapour+' kPa(a). Calculate their pressure difference in pascals.',(x.surface-x.vapour)*1000,'Pa',['Subtract pressures on the same absolute reference.','Multiply kPa by 1000 to obtain Pa.','Δp = '+num((x.surface-x.vapour)*1000)+' Pa.']);
 case 'refrigeration-energy':return question('The evaporator absorbs '+num(z.cooling)+' kW and compressor input is '+num(z.work)+' kW. Calculate condenser heat rejection.',z.rejected,'kW',['Steady energy balance: Qreject = Qcool + W.','Qreject = '+num(z.rejected)+' kW.']);
 case 'lift-cross-curves':return question('Resulting displacement is '+num(z.mass)+' t in water of density '+x.density+' t/m³. Calculate the submerged volume.',z.mass/x.density,'m³',['Displacement mass = water density × submerged volume.','V = Δ/ρ.','V = '+num(z.mass/x.density)+' m³.']);
 default:throw Error('No applied question is defined for this module.');}}
function read(){const page=(location.pathname.split('/').pop()||'index').replace(/(?:\.html)?$/,'')+'.html',localHash=location.hash.slice(1),registry=root.MT_INTERACTIVE_MODULES||[];
 if(root.MT_MODEL_UI){const state=root.MT_MODEL_UI.state();if(!state)throw Error('Correct the model inputs before continuing.');const id=registry.find(m=>['model-lab.html#'+state.id,'advanced-lab.html#'+state.id].includes(m.url))?.id;if(!id)throw Error('Unknown engineering model.');const results=Object.fromEntries((state.result.metrics||[]).filter(([label])=>!/residual/i.test(label)).map(([label,value,unit])=>[label+(unit?' ('+unit+')':''),value]));if(!state.result.metrics){const snapshot=root.MT_EDUCATION_SNAPSHOT();Object.assign(results,snapshot.results);}return build(id,state.title,state.inputs,results,state.result.exercise||legacyQuestion(id,state.inputs,state.result));}
 for(const [uiName,modelsName]of [['MT_EXAMPLE_UI','MT_EXAMPLE_MODELS'],['MT_EXPLORER_UI','MT_EXPLORERS']]){const ui=root[uiName];if(!ui)continue;const id=document.getElementById('module').value,schema=ui.schemas[id],x=fields(document.getElementById('experiment')),z=root[modelsName][id](x),present=schema.present(z);return build(id,schema.title,x,present.results,legacyQuestion(id,x,modelsName==='MT_EXAMPLE_MODELS'?present:z));}
 if(page==='labs.html'){const id=['stability','controls','engine'].includes(localHash)?localHash:'stability',M=root.MT_LABS;root.MT_LAB_SNAPSHOT(id); // Reject any currently invalid displayed state.
  if(id==='stability'){const x=fields(document.getElementById('stability-form')),z=M.stability(x),arm=z.curve.find(q=>q.angle===10).gz;return build(id,'GZ and free surface',x,{'Corrected GM (m)':z.gm,'Free-surface correction (m)':z.fsc,'KG after relocation (m)':z.movedKG,'Maximum sampled GZ (m)':z.maximum.gz,'Signed area 0–30° (m·rad)':z.area30,'Initial positive range ends (°)':z.zero},question('At 10° heel, the model GZ is '+num(arm)+' m and displacement is '+x.displacement+' t. Calculate the signed restoring mass moment.',x.displacement*arm,'t·m',['Restoring mass moment = displacement mass × GZ.','This is t·m, not N·m.','Moment = '+num(x.displacement*arm)+' t·m.']));}
  if(id==='engine'){const x=fields(document.getElementById('engine-form'));x.cycles=Number(x.cycles);const z=M.engine(x);return build(id,'Engine and fuel',x,{'Brake power (kW)':z.brake,'Indicated power (kW)':z.indicated,'Fuel flow (kg/h)':z.fuel,'SFOC (g/kWh)':z.sfoc,'Swept volume (L)':z.volume*1000,'Mean piston speed (m/s)':z.pistonSpeed},question('The current steady fuel flow is '+num(z.fuel)+' kg/h. Calculate fuel consumed in 30 minutes.',z.fuel/2,'kg',['30 minutes = 0.5 hour.','Fuel mass = fuel flow × time.','m = '+num(z.fuel/2)+' kg.']));}
  const signal=fields(document.getElementById('signal-form')),pid=fields(document.getElementById('pid-form')),v=M.scale(signal.value,signal.lrv,signal.urv,signal.inverse==='true'),end=M.pid(pid).at(-1),range=signal.urv-signal.lrv,q=signal.inverse==='true'?question('A transmitter span is '+signal.lrv+' to '+signal.urv+'. For '+signal.value+' mA, calculate the engineering value.',v,'engineering units',['Fraction of span = (I − 4)/16.','Engineering value = LRV + fraction × (URV − LRV).','Value = '+num(v)+'.']):question('A transmitter spans '+signal.lrv+' to '+signal.urv+'. The engineering input is '+signal.value+'. Calculate its ideal output current.',v,'mA',['Fraction of span = (value − LRV)/(URV − LRV).','I = 4 + 16 × fraction.','I = '+num(v)+' mA.']);if(!Number.isFinite(range)||range===0)throw Error('Use a nonzero transmitter span.');return build(id,'Signals and PID',{signal,pid},{['Signal output ('+(signal.inverse==='true'?'engineering units':'mA')+')']:v,'PV at 180 s (%)':end.pv,'Controller output at 180 s (%)':end.u,'Error at 180 s (percentage points)':end.sp-end.pv},q);
 }
 if(page==='cargo.html'){const snapshot=root.MT_CARGO_UI.snapshot(),x=snapshot.inputs,z=root.MT_CARGO.calculate(x).final;return build('cargo',snapshot.title,x,snapshot.results,question('The final displacement is '+num(z.displacement)+' t and KG is '+num(z.kg)+' m. Calculate the vertical mass moment about the keel.',z.displacement*z.kg,'t·m',['Vertical mass moment = displacement × KG.','Keep mass-moment units t·m separate from force-moment units.','Mv = '+num(z.displacement*z.kg)+' t·m.']));}
 if(page==='mollier.html'){const s=root.MT_MOLLIER_SNAPSHOT(),a=s.results['State A · h (kJ/kg)'],b=s.results['State B · h (kJ/kg)'];return build('mollier',s.title,s.inputs,s.results,question('For the displayed enthalpies hA='+num(a)+' and hB='+num(b)+' kJ/kg, calculate the signed rate ṁ(hA−hB) at a mass flow of 2.5 kg/s.',2.5*(a-b),'kW',['Use the signed enthalpy difference on one reference datum.','kg/s × kJ/kg gives kW.','Rate = '+num(2.5*(a-b))+' kW.']));}
 throw Error('The current module has no learning context.');
}
root.MT_LEARNING_CYCLE_CONTEXT={read,canonical,metricRows};
})(typeof window!=='undefined'?window:globalThis);
